CREATE COLUMN TABLE "TEST_AP"."NNM2" ("ObjectCode" NVARCHAR(20) NOT NULL , "UserSign" SMALLINT CS_INT NOT NULL , "Series" INTEGER CS_INT, "DocSubType" NVARCHAR(2) DEFAULT '--' NOT NULL , PRIMARY KEY ("ObjectCode", "DocSubType", "UserSign")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "NNM2_USER" ON "TEST_AP"."NNM2" ( "UserSign" ASC )